/// <summary>
/// business event trigger
/// </summary>
/// <returns>BusinessEventsBase</returns>
protected BusinessEventsBase getBusinessEvent()
{
   if (CustInvoiceTable::findSourceDocumentHeader(sourceDocumentHeader.RecId).METClaimId)
   {
        METClaimCustFreeTextInvoicePostedBusinessEvent::newFromSourceDocumentHeaderRecId(sourceDocumentHeader.RecId).send();
   }

   return  next getBusinessEvent();
}
